(async()=>{const out={},run=async(n,f)=>{document.title=n;try{out[n]=await f()}catch(e){out[n]=e.name}},image=new Image();const read=()=>[image.complete,image.naturalWidth,image.naturalHeight,image.width,image.height,image.currentSrc===image.src];out.initial=read();await run('png',async()=>{const p=new Promise(resolve=>{image.onload=()=>resolve('load');image.onerror=()=>resolve('error')});image.src='data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAAAIAAAABCAYAAAD0In+KAAAADklEQVR4nGP4z8DwHwQBEPgD/U6VwW8AAAAASUVORK5CYII=';const immediate=read();const event=await p;await image.decode();return [immediate,event,read()]});out.attrs=(()=>{image.width=10;image.height=20;return [read(),image.getAttribute('width'),image.getAttribute('height')]})();out.draw=(()=>{const c=document.createElement('canvas');c.width=2;c.height=1;const x=c.getContext('2d');x.drawImage(image,0,0);return Array.from(x.getImageData(0,0,2,1).data)})();await run('broken',async()=>{const p=new Promise(resolve=>image.onerror=()=>resolve());image.src='data:image/png;base64,AA==';await p;return [read(),await image.decode().then(()=>true,e=>e.name)]});await run('svg',async()=>{const p=new Promise(resolve=>{image.onload=()=>resolve('load');image.onerror=()=>resolve('error')});image.src='data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="12" height="7"/>');return [await p,read()]});image.removeAttribute('src');out.removed=read();document.title='done';return out})()